package com.spaceagent.platform.runtime.infrastructure.persistence;
import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.runtime.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.*;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres") public class PostgresRuntimeGraphSessionRepository implements RuntimeGraphSessionRepository{private final JdbcTemplate j;private final ObjectMapper json;public PostgresRuntimeGraphSessionRepository(JdbcTemplate j,ObjectMapper json){this.j=j;this.json=json;}public void insert(RuntimeGraphSession s){j.update("INSERT INTO platform_runtime_graph_sessions(id,tenant_id,owner_id,agent_run_id,bundle_hash,cursor_sequence,completed_command_ids,pending_command_id,pending_input_hash,state,revision,created_at,updated_at) VALUES(CAST(? AS UUID),?,?,?,?,? ,CAST(? AS jsonb),?,?,?, ?,?,?)",s.id(),s.tenantId(),s.ownerUserId(),s.agentRunId(),s.bundleHash(),s.cursorSequence(),write(s.completedCommandIds()),s.pendingCommandId(),s.pendingInputHash(),s.state().name(),s.revision(),ts(s.createdAt()),ts(s.updatedAt()));}public Optional<RuntimeGraphSession> findById(String t,String o,String id){return j.query("SELECT * FROM platform_runtime_graph_sessions WHERE id=CAST(? AS UUID) AND tenant_id=? AND owner_id=?",this::map,id,t,o).stream().findFirst();}public Optional<RuntimeGraphSession> findByRunId(String t,String o,String run){return j.query("SELECT * FROM platform_runtime_graph_sessions WHERE agent_run_id=? AND tenant_id=? AND owner_id=?",this::map,run,t,o).stream().findFirst();}public boolean update(RuntimeGraphSession s,long rev,GraphSessionState state){return j.update("UPDATE platform_runtime_graph_sessions SET cursor_sequence=?,completed_command_ids=CAST(? AS jsonb),pending_command_id=?,pending_input_hash=?,state=?,revision=?,updated_at=? WHERE id=CAST(? AS UUID) AND revision=? AND state=?",s.cursorSequence(),write(s.completedCommandIds()),s.pendingCommandId(),s.pendingInputHash(),s.state().name(),s.revision(),ts(s.updatedAt()),s.id(),rev,state.name())==1;}public RuntimeGraphCommand insertCommandIfAbsent(RuntimeGraphCommand c){try{j.update("INSERT INTO platform_runtime_graph_commands(graph_session_id,command_id,input_hash,command_kind,next_cursor_sequence,payload_json,state,attempt,execution_owner,execution_token,execution_fencing_token,safe_error_code,revision,created_at,updated_at) VALUES(CAST(? AS UUID),?,?,?, ?,CAST(? AS jsonb),?,?,?,CAST(? AS UUID),?,?, ?,?,?)",c.graphSessionId(),c.commandId(),c.inputHash(),c.kind().name(),c.nextCursorSequence(),c.payloadJson(),c.state().name(),c.attempt(),c.executionOwner(),c.executionToken(),c.executionFencingToken(),c.safeErrorCode(),c.revision(),ts(c.createdAt()),ts(c.updatedAt()));return c;}catch(org.springframework.dao.DataIntegrityViolationException e){var old=findCommand(c.graphSessionId(),c.commandId()).orElseThrow(()->e);if(!old.inputHash().equals(c.inputHash()))throw new IllegalStateException("graph command input conflict",e);return old;}}public Optional<RuntimeGraphCommand> findCommand(String s,String c){return j.query("SELECT * FROM platform_runtime_graph_commands WHERE graph_session_id=CAST(? AS UUID) AND command_id=?",this::command,s,c).stream().findFirst();}public boolean updateCommand(RuntimeGraphCommand c,long rev,RuntimeGraphCommand.State state){return j.update("UPDATE platform_runtime_graph_commands SET state=?,attempt=?,execution_owner=?,execution_token=CAST(? AS UUID),execution_fencing_token=?,safe_error_code=?,revision=?,updated_at=? WHERE graph_session_id=CAST(? AS UUID) AND command_id=? AND revision=? AND state=?",c.state().name(),c.attempt(),c.executionOwner(),c.executionToken(),c.executionFencingToken(),c.safeErrorCode(),c.revision(),ts(c.updatedAt()),c.graphSessionId(),c.commandId(),rev,state.name())==1;}public int cleanupCompletedBefore(Instant before){return j.update("DELETE FROM platform_runtime_graph_sessions WHERE state='COMPLETED' AND updated_at<?",ts(before));}private RuntimeGraphCommand command(ResultSet r,int n)throws SQLException{return new RuntimeGraphCommand(r.getString("graph_session_id"),r.getString("command_id"),r.getString("input_hash"),com.spaceagent.platform.runtime.domain.multiagent.GraphV2Contract.Kind.valueOf(r.getString("command_kind")),r.getLong("next_cursor_sequence"),canonical(r.getString("payload_json")),RuntimeGraphCommand.State.valueOf(r.getString("state")),r.getInt("attempt"),r.getString("execution_owner"),r.getString("execution_token"),(Long)r.getObject("execution_fencing_token"),r.getString("safe_error_code"),r.getLong("revision"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}private String canonical(String v){try{return json.writeValueAsString(json.readTree(v));}catch(Exception e){throw new IllegalStateException(e);}}private RuntimeGraphSession map(ResultSet r,int n)throws SQLException{return new RuntimeGraphSession(r.getString("id"),r.getString("tenant_id"),r.getString("owner_id"),r.getString("agent_run_id"),r.getString("bundle_hash"),r.getLong("cursor_sequence"),read(r.getString("completed_command_ids")),r.getString("pending_command_id"),r.getString("pending_input_hash"),GraphSessionState.valueOf(r.getString("state")),r.getLong("revision"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}private List<String> read(String v){try{return json.readValue(v,json.getTypeFactory().constructCollectionType(List.class,String.class));}catch(Exception e){throw new IllegalStateException(e);}}private static Timestamp ts(Instant v){return Timestamp.from(v);}}
